new='''/**
 * Whether the tokens contain a link at any level of nesting
 */
function containsLink(tokens: Token[] | undefined): boolean {
  if (!tokens) {
    return false;
  }
  for (const token of tokens) {
    if (token.type === 'link' || containsLink((token as Tokens.Generic).tokens)) {
      return true;
    }
  }
  return false;
}

function outputLink(cap: string[], link: Pick<Tokens.Link, 'href' | 'title'>, raw: string, lexer: _Lexer, rules: Rules): Tokens.Link | Tokens.Image | undefined {
  const href = link.href;
  const title = link.title || null;
  const text = cap[1].replace(rules.other.outputLinkReplace, '$1');
  const isImage = cap[0].charAt(0) === '!';

  const prevInLink = lexer.state.inLink;
  // the description of an image is not link text, it may contain links
  lexer.state.inLink = isImage ? prevInLink : true;
  const tokens = lexer.inlineTokens(text);
  lexer.state.inLink = prevInLink;

  if (!isImage && containsLink(tokens)) {
    // links may not contain other links, at any level of nesting:
    // the inner link wins and the outer brackets are literal text
    return;
  }

  return {
    type: isImage ? 'image' : 'link',
    raw,
    href,
    title,
    text,
    tokens,
  };
}

'''
s=s.replace(old,new)
open(p,'w',encoding='utf-8',newline='').write(s.replace('\n',nl))
